import hashlib,os,re,subprocess,sys
fail=[]
def raw(p): return open(p,'rb').read()
def txt(p): return raw(p).decode('utf-8')
G=list(d['finalSha256'])
for p,h in d['readOnlyInputSha256'].items():
    if hashlib.sha256(raw(p)).hexdigest()!=h: fail.append('input drift '+p)
for p,h in d['finalSha256'].items():
    if hashlib.sha256(raw(p)).hexdigest()!=h: fail.append('final hash '+p)
for g in G:
    for m in re.finditer(r'\]\(([^)\s#]+)(?:#[^)]*)?\)',txt(g)):
        t=m.group(1)
        if t.startswith(('http:','https:','mailto:')): continue
        if not os.path.exists(os.path.normpath(os.path.join(os.path.dirname(g),t))): fail.append('broken link '+g+' -> '+t)
for p,cap in d['lineCaps'].items():
    if os.path.exists(p) and len(txt(p).splitlines())>cap: fail.append('size '+p)
def head(p): return subprocess.run(['git','show','HEAD:'+p],capture_output=True).stdout.decode('utf-8').splitlines()
for p,drop in (('docs/GET_STARTED.md',(9,10)),('docs/reference/CVF_INTERNAL_USER_GUIDE.md',(5,))):
    lines=txt(p).splitlines()
    cur=[l for i,l in enumerate(lines) if i not in drop]
    if cur!=head(p): fail.append('preservation '+p)
    if 'CVF_QUICK_ORIENTATION' not in lines[drop[0]]: fail.append('insertion position '+p)
q=txt('docs/guides/CVF_QUICK_ORIENTATION.md')
for t in d['mustContain']:
    if t not in q: fail.append('missing '+t)
for t in d['mustNotContain']:
    if t in q: fail.append('stale '+t)
for l in q.splitlines():
    if '2026-04-21' in l and not any(k in l for k in ('Packet','Limitations','lịch sử','Viết lại')): fail.append('undated april line: '+l[:40])
st=subprocess.run(['git','status','--short','--untracked-files=all'],capture_output=True,text=True).stdout.splitlines()
if sorted(x[3:] for x in st)!=sorted(d['exactPaths']): fail.append('path set '+repr(st))
print('FAIL' if fail else 'PASS_STATIC_ONLY',ascii(fail))
sys.exit(1 if fail else 0)
